/** Transparent, fully local role-play. NOT generated by AI and never graded as AI feedback. */
export const offlineFollowUps:Record<string,readonly string[]>={
 'small-talk':['What do you usually do after work?','What do you like about your city?','It was nice talking to you. Would you like to meet for coffee?'],
 coffee:['What size would you like: small, medium, or large?','Would you like anything else with your coffee?','That will be five dollars. Will you pay by card?'],
 apartment:['How many people will live in the apartment?','Would you like to schedule a viewing this weekend?','Do you have any questions about the deposit?'],
 airport:['Could I see your boarding pass, please?','Your flight is delayed by thirty minutes. Do you have any questions?','Would you like directions to gate B12?'],
 doctor:['What symptoms are you experiencing?','Would morning or afternoon work better for you?','Could you confirm your preferred appointment date?'],
 'job-interview':['What would you do if a customer was angry?','How do you prioritize several support tickets?','Do you have any questions about the role?'],
 'payment-pending':['My transaction ID is TX-12345. How long will your review take?','Could you tell me what information you need?','Thank you. How will I receive an update?'],
 refund:['The order number is ORD-204. What happens next?','Can you explain the refund process?','How will I know when the request is resolved?'],
 salary:['How does that range compare to your experience?','What benefits matter most to you?','Do you have any questions about the compensation package?'],
 'team-meeting':['What caused the delay, and what is the current status?','What action would you suggest to prevent it from happening again?','Who will own the next steps?'],
 complaint:['I have already shared my transaction ID. What can you do now?','Can you explain the next step clearly?','When can I expect another update?']
};
export const offlineCourseFollowUps={
 america:['Could you explain what you need in more detail?','What time or date would work best for you?','Thank you. Is there anything else you would like to ask?'],
 work:['Could you clarify which transaction or request you mean?','What would be the next step in your investigation?','How will you keep the customer informed?']
} as const;
export function offlineNextLine(scenarioId:string|null,turn:number,courseKind?:'america'|'work'):string|null{
 const followUps=courseKind?offlineCourseFollowUps[courseKind]:offlineFollowUps[scenarioId||''];
 if(!followUps||!Number.isInteger(turn)||turn<0)return null;
 return followUps[turn]??null;
}
export function offlineProgress(scenarioId:string|null,count:number,courseKind?:'america'|'work'):{total:number;finished:boolean}{
 const list=courseKind?offlineCourseFollowUps[courseKind]:offlineFollowUps[scenarioId||'']||[];
 return {total:list.length+1,finished:count>=list.length+1};
}
